INSERT INTO tracks (id, slug, title, summary, weeks, default_start, highlights, sort_order) VALUES
(1, 'fullstack', 'Full-stack interview prep', 'Eight weeks to prepare for senior roles: JavaScript, Node.js, React, Next.js, Laravel, system design and leadership.', 8, '2026-11-02', NULL, 1),
(2, 'ai', 'AI engineering', 'Four weeks to learn — and explain in interviews — LLMs, RAG, agents, MCP, evals and AI security, using the stack you already know.', 4, '2026-11-02', 'AI makes writing code cheaper, so judgement becomes more valuable: architecture, code review, debugging, security and trade-offs — exactly what 10 years of experience gives you.\nMost of an AI feature is classic engineering you already know: APIs, queues, caching, auth, databases, streaming UIs, observability. You only need to add the AI-specific 20%.\nThat 20% is: how LLMs behave, prompting & context, structured output & tools, embeddings & RAG, agents & MCP, evals, AI security and cost control — all covered in AI Study Notes.\nCompanies hiring senior engineers in 2026 increasingly ask: "Have you shipped an AI feature?" and "How does your team use AI tools safely?" — one real project answers both.\nUse AI as a tutor and sparring partner while you prepare for interviews, but verify everything: run the code, read the docs, check the numbers.', 2)
