INSERT INTO skills (id, track_id, skill, how_ai_changes, use_ai, build_this, talking_point, watch_out, related_notes, sort_order) VALUES
(1, 2, 'JavaScript / TypeScript', 'AI writes boilerplate fast, so deep fundamentals (event loop, async, types) become the differentiator when you review AI code. TypeScript types + zod schemas make both AI-generated code and AI responses safer.', 'Ask AI to generate event-loop/closure puzzles and polyfill drills; ask it to explain its code line by line; have it review your utilities for edge cases — then run everything.', 'A typed LLM client wrapper: timeouts, retries with backoff, streaming, zod-validated structured output, token/cost logging.', '"I validate model output at runtime with schemas — the type system ends at the network boundary."', 'AI is often confidently wrong on event-loop ordering and coercion; always execute the snippet.', 'AI-N04, AI-N12, AI-N20', 1),
(2, 2, 'Node.js', 'Node is the default glue for AI backends: streaming responses, queues for long jobs, MCP tool servers, provider SDKs.', 'Let AI explain flame graphs and heap snapshots; generate k6 load-test scripts; then confirm with your own measurements.', 'An AI gateway service: model routing, per-user rate limits, Redis cache, BullMQ for long jobs, provider fallback, cost metrics.', 'Streaming with backpressure, idempotent retries for LLM calls, cost and quota controls per tenant.', 'Unbounded concurrency to LLM APIs (429s and cost spikes); API keys or prompts with PII leaking into logs.', 'AI-N10, AI-N12, AI-N16, AI-N18', 2),
(3, 2, 'React', 'New UX patterns: streaming text, optimistic messages, generative UI (tool results rendered as components), citations, feedback buttons.', 'Ask AI to critique your component APIs, write React Testing Library tests, and interpret Profiler output — verify by re-measuring.', 'A polished chat UI: streaming, stop/regenerate, safe markdown + code rendering, 👍/👎 feedback, aria-live accessibility.', '"I cut perceived latency with streaming and kept the UI responsive with transitions and virtualisation."', 'Rendering model output as raw HTML (XSS) — always sanitise markdown.', 'AI-N11, AI-N14', 3),
(4, 2, 'Next.js', 'Route handlers and Server Actions become AI endpoints; Server Components do retrieval close to the data; caching decisions get more important (and riskier).', 'Scaffold with an AI SDK, then refactor to your Data Access Layer + auth; ask AI to explain caching behaviour and verify with logs.', '"Chat with your docs": upload PDFs, RAG with citations, per-user auth, streaming answers, cached embeddings.', 'Where AI calls live (server only), protecting keys, multi-tenant isolation, cache tags per tenant.', 'Calling providers from the browser with exposed keys; caching per-user answers in shared caches.', 'AI-N08, AI-N14, AI-N17', 4),
(5, 2, 'Laravel / PHP', 'Laravel 13 ships a first-party AI SDK and native vector search, so AI features become everyday Laravel work: agents, tools, queues, policies, caching, Pest fakes. Laravel Boost gives coding agents Laravel-aware context.', 'Install Laravel Boost so your coding agent knows your schema, logs and the right docs; ask AI for upgrade plans and Pest tests — review every diff.', 'AI ticket triage: queued agent classifies and summarises tickets (structured output), embeddings in pgvector, "similar tickets" search, human approval before refunds.', 'Queue + retry + afterCommit for AI jobs; policies limiting what AI tools can do; cost per tenant.', 'Synchronous AI calls inside web requests (timeouts); saving model output into models without validation.', 'AI-N13, AI-N07, AI-N09', 5),
(6, 2, 'System Design', 'New building blocks: LLM gateway, embedding pipeline, vector store, reranker, eval pipeline, guardrails, approval workflows.', 'Ask AI to play the interviewer and challenge your trade-offs; practise "design an AI assistant / RAG / agent" questions.', 'A design doc for a RAG support bot with estimates: tokens/day, cost/month, latency budget, failure modes.', 'Latency budget, fallbacks when the model is down, caching, evals, tenant isolation.', 'Non-determinism: design for validation, retries and human-in-the-loop on risky actions.', 'AI-N21, AI-N08, AI-N16', 6),
(7, 2, 'Databases', 'Vector columns and indexes live next to relational data (pgvector, MariaDB vectors); hybrid search and metadata filtering become core skills.', 'Have AI explain EXPLAIN plans and suggest indexes — then benchmark before and after.', 'Hybrid search (full-text + vector) with tenant/permission filters and reranking.', 'pgvector HNSW vs a dedicated vector DB; re-embedding when the model changes; storage cost of vectors.', 'AI-suggested migrations that lock large tables; trusting suggested indexes without measuring.', 'AI-N07, AI-N08', 7),
(8, 2, 'DevOps & Cloud', 'AI workloads need secret management, quotas, cost monitoring, regional hosting and managed model endpoints (Bedrock, Vertex AI, Azure).', 'Let AI draft Dockerfiles, CI pipelines and Terraform; review them for least privilege; paste failing CI logs and ask for root causes.', 'A CI job that runs the AI eval suite and posts quality + cost results on every pull request.', 'Provider fallbacks, budget alerts, data residency (e.g., ap-south-1 Mumbai).', 'AI-generated IaC with over-broad IAM permissions; secrets ending up in prompts or logs.', 'AI-N16, AI-N18, AI-N22', 8),
(9, 2, 'Testing & Quality', 'AI writes tests quickly — your value is deciding what to test and judging test quality. Evals are the test suite for AI features.', 'Generate edge-case tests with AI, then use mutation testing to see if they actually catch bugs.', 'A golden-set eval harness with LLM-as-judge and a regression threshold in CI.', 'How you test non-deterministic features: schema checks, retrieval metrics, evals, fixed seeds/temperature where possible.', 'Tautological AI tests that just mirror the implementation.', 'AI-N15', 9),
(10, 2, 'Security', 'A new attack surface (prompt injection, data exfiltration through tools, excessive agency) — and AI also helps with code review and threat modelling.', 'Ask AI to threat-model a feature (STRIDE) and review code for OWASP issues — verify each finding.', 'Guardrail middleware: PII redaction, injection heuristics, output schema validation, tool allowlists, audit logs.', 'OWASP Top 10 for LLM Applications; "retrieved content is untrusted data"; limit what the model can do.', 'Hallucinated package names (slopsquatting) and insecure AI-generated code.', 'AI-N17, AI-N10', 10),
(11, 2, 'Leadership & Behavioural', 'Senior engineers and leads are expected to set AI adoption policy, measure impact and upskill the team.', 'Practise STAR stories with AI as the interviewer and ask for critique of structure — you supply the real facts.', 'A team AI playbook: approved tools, data rules, review standards, CLAUDE.md/AGENTS.md conventions, metrics.', '"We adopted AI assistants with guardrails; cycle time improved while defect rate stayed flat" — with your real numbers.', 'Claiming productivity gains you can\'t back up with data.', 'AI-N20, AI-N22', 11),
(12, 2, 'Career & job search', '"Full-stack engineer who ships AI features" is a strong position in the 2026 market.', 'Use AI to tailor your resume to each job description, research companies and run mock interviews — fact-check everything it writes.', 'One public capstone (GitHub + README + 2-minute demo): Laravel or Next.js + RAG + tools + evals + cost numbers.', 'End-to-end ownership of an AI feature: problem → design → evals → production metrics.', 'Generic, AI-sounding resume text or overstated claims.', 'AI-N19, AI-N21', 12)
